import { AvatarComponent } from './avatar.component';
const meta = {
    title: 'Components/Avatar',
    component: AvatarComponent,
    tags: ['autodocs'],
    argTypes: {
        size: { control: 'select', options: ['xs', 'sm', 'md', 'lg', 'xl'] },
        shape: { control: 'select', options: ['circle', 'rounded'] },
        name: { control: 'text' },
        src: { control: 'text' },
        alt: { control: 'text' },
    },
};
export default meta;
export const Initials = {
    args: { name: 'Jane Doe', size: 'md', shape: 'circle' },
};
export const WithImage = {
    args: {
        src: 'https://i.pravatar.cc/80',
        alt: 'User avatar',
        size: 'md',
        shape: 'circle',
    },
};
export const Rounded = {
    args: { name: 'Blueprint DS', size: 'md', shape: 'rounded' },
};
export const SingleName = {
    args: { name: 'Alex', size: 'md', shape: 'circle' },
};
export const Sizes = {
    render: () => ({
        template: `
      <div style="display:flex;align-items:center;gap:12px;padding:8px;">
        <dsb-avatar name="Jane Doe" size="xs"></dsb-avatar>
        <dsb-avatar name="Jane Doe" size="sm"></dsb-avatar>
        <dsb-avatar name="Jane Doe" size="md"></dsb-avatar>
        <dsb-avatar name="Jane Doe" size="lg"></dsb-avatar>
        <dsb-avatar name="Jane Doe" size="xl"></dsb-avatar>
      </div>`,
    }),
};
export const Group = {
    render: () => ({
        template: `
      <div style="display:flex;align-items:center;padding:8px;">
        <div style="display:flex;">
          <span style="z-index:4;outline:2px solid #fff;border-radius:50%;"><dsb-avatar name="Alice B"></dsb-avatar></span>
          <span style="z-index:3;margin-left:-10px;outline:2px solid #fff;border-radius:50%;"><dsb-avatar name="Bob C"></dsb-avatar></span>
          <span style="z-index:2;margin-left:-10px;outline:2px solid #fff;border-radius:50%;"><dsb-avatar name="Carol D"></dsb-avatar></span>
          <span style="z-index:1;margin-left:-10px;outline:2px solid #fff;border-radius:50%;"><dsb-avatar name="Dan E"></dsb-avatar></span>
        </div>
      </div>`,
    }),
};
